output_text:
[
  {
    "id": "cart_before_sales_floor",
    "text": "A shopper must not leave the entry/cart-station area for the sales floor without a cart.",
    "abstraction": {
      "state_properties": {
        "cartStation": "at(1,7)",
        "awayFromCartStation": {
          "not": "at(1,7)"
        }
      },
      "events": {
        "leaveCartStationWithoutCart": {
          "pre": {
            "and": [
              "cartStation",
              {
                "not": "hasCart"
              },
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": {
            "and": [
              "awayFromCartStation",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leaveCartStationWithoutCart"
    }
  },
  {
    "id": "no_cart_single_file",
    "text": "Carts are forbidden inside single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartInSingleFileAisle": {
          "and": [
            "hasCart",
            "singleFileAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartInSingleFileAisle"
    }
  },
  {
    "id": "no_push_cart_into_single_file",
    "text": "A shopper must not push a cart from a broad aisle into a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After returning from a single-file aisle without a cart, the shopper is obliged to retrieve the parked cart before finishing.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartParkBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "returnToCartBayWithoutCart": {
          "pre": {
            "and": [
              "singleFileAisle",
              {
                "not": "hasCart"
              },
              "S"
            ]
          },
          "post": {
            "and": [
              "cartParkBay",
              {
                "not": "hasCart"
              }
            ]
          }
        },
        "pickupCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returnToCartBayWithoutCart",
      "discharge": "pickupCart"
    }
  },
  {
    "id": "cart_for_wide_shelf_service",
    "text": "Shelf interactions from cart-accessible aisles must be done while holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartAccessibleShelfFront": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "cartAccessibleShelfFront",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "interact_only_at_service_points",
    "text": "Interactions are only permitted at service points: the cart station, approved cart-parking bays, or cells adjacent to shelves.",
    "abstraction": {
      "state_properties": {
        "cartStation": "at(1,7)",
        "cartParkBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "servicePoint": {
          "or": [
            "cartStation",
            "cartParkBay",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "servicePoint"
          }
        ]
      }
    }
  },
  {
    "id": "eastbound_cart_traffic",
    "text": "Cart traffic in horizontal shopping aisles is one-way eastbound, so westbound cart movement is forbidden there.",
    "abstraction": {
      "state_properties": {
        "horizontalShoppingAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "horizontalShoppingAisle",
          "W"
        ]
      }
    }
  },
  {
    "id": "park_cart_only_at_aisle_mouth",
    "text": "A cart may be parked only at the wide mouths of the single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wideEnoughToPark": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "approvedCartParking": {
          "and": [
            "singleFileAisleMouth",
            "wideEnoughToPark"
          ]
        }
      },
      "events": {
        "dropCartOutsideApprovedBay": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              {
                "not": "approvedCartParking"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "dropCartOutsideApprovedBay"
    }
  }
]
